-- ===========================================================================
-- SEED: importa a Tabela TACO (UNICAMP, 4a ed., 597 alimentos) para a
-- biblioteca de alimentos do nutri. Valores por 100 g. Fonte marcada como TACO.
-- Fonte dos dados: github.com/marcelosanto/tabela_taco (TACO.json).
-- ---------------------------------------------------------------------------
-- nutri_id abaixo = o nutri dono dos alimentos. Troque se for outro nutri.
-- Seguro re-rodar: apaga os TACO existentes desse nutri e reinsere.
-- Rodar no SQL Editor do Supabase (depois de db/dieta_schema.sql).
-- ===========================================================================
alter table public.alimentos add column if not exists fonte text;

delete from public.alimentos
 where fonte = 'TACO' and nutri_id = '71935ff7-19a0-453a-9ae4-fa1d73c13a58';

